import React from "react";
import { createRoot } from "react-dom/client";
import { ThemeProvider } from "@/components/theme/theme-provider";
import { TeacherSessions, SessionPortal, GroupJoin } from "@/components/group-mock/session-ui";
import { WRITING_SEED } from "@/lib/ielts/content";
const kind=new URLSearchParams(location.search).get("kind")||"teacher";
const reviewer=kind==="review";const isTeacher=kind!=="student";
const participants=[{id:"p1",attemptId:"a1",ordinal:0,name:"Dilnoza Karimova",ready:true,version:0,publishedAt:null,attempt:{current:reviewer?3:0,status:reviewer?"finished":"active",updatedAt:new Date().toISOString(),sectionDeadline:null,results:{LISTENING:{band:7},READING:{band:6.5}}}},{id:"p2",attemptId:"a2",ordinal:1,name:"Aziz Akramov",ready:true,version:0,publishedAt:null,attempt:{current:0,status:"active",updatedAt:new Date().toISOString(),sectionDeadline:null,results:{}}}];
let session:any={serverNow:Date.now(),id:"s",title:"Saturday Academic Mock",groupName:"IELTS B2 · Morning class",teacher:isTeacher,state:reviewer?"review":"lobby",version:0,code:"A1B2C3D4",distribution:"unique",capacity:2,uniqueCapacity:2,participants:isTeacher?participants:[participants[0]],startedAt:null,audioUrl:location.origin+"/tone.wav"};
const task=WRITING_SEED.task1[0];let detail:any={id:"p1",version:0,publishedAt:null,review:null,work:{task1:{title:task.title,prompt:task.prompt,chart:task.chart,essay:"The chart compares weekly leisure habits across four age groups. Overall, television viewing increases with age, whereas social media is most popular among the youngest people. Exercise remains lower than the other activities in most groups."},task2:{title:"Education and practical skills",prompt:"Some people believe schools should focus on academic subjects, while others prefer practical skills. Discuss both views and give your own opinion.",essay:"Schools need to combine academic knowledge with practical experience. Students benefit from theoretical foundations, but they also need opportunities to use those ideas in everyday life. I believe a balanced curriculum best prepares young people for work and further education."}}};
(window as any).__writes=[];(window as any).__conflict=false;
window.fetch=async(url,init)=>{const u=String(url),method=init?.method||"GET";if(method==="GET")return new Response(JSON.stringify(u.endsWith("/api/mock-sessions")?{groups:[{id:"g",name:session.groupName}],sessions:[{id:"s",title:session.title,state:session.state,code:session.code}]}:{...session,serverNow:Date.now(),detail:u.includes("participant=")?detail:null}));const input=JSON.parse(String(init?.body||"{}"));(window as any).__writes.push({method,input});if(method==="PUT"){if((window as any).__conflict){(window as any).__conflict=false;return new Response(JSON.stringify({error:"Another review saved first. Reload before marking."}),{status:409});}detail={...detail,review:input,version:detail.version+1};if(input.publish){detail.publishedAt=new Date().toISOString();participants[0].publishedAt=detail.publishedAt;}return new Response(JSON.stringify(detail));}if(input.action==="start"){session={...session,state:"running",version:1,startedAt:new Date(Date.now()+15000).toISOString()};}if(input.action==="ready")participants[0].ready=true;if(input.action==="end")session.state="review";if(input.code)return new Response(JSON.stringify({error:"Session unavailable for your class."}),{status:404});return new Response(JSON.stringify({...session,sessionId:"s"}));};
