createRoot(document.getElementById("root")!).render(<ThemeProvider>{kind==="list"?<TeacherSessions enabled/>:kind==="join"?<main className="min-h-screen premium-gradient p-4"><GroupJoin enabled/></main>:<SessionPortal id="s"/>}</ThemeProvider>);
